		fresh.Close()
		t.Fatal("changed source incorrectly reused the legacy cache")
	}
	if err != nil {
		t.Fatal(err)
	}
	rebuilt, err := openHistoryFTS(brainDir, index)
	if err != nil {
		t.Fatalf("rebuild for duplicate IDs: %v", err)
	}
	defer rebuilt.Close()
	var rows, ids int
